import { and, eq } from "@holler/core/db";
import { schema } from "../db";
import { activityOf, recordChange } from "./audit";
import type { ServiceContext } from "./context";

export async function removeViewer(ctx: ServiceContext, hollerId: string, memberId: string) {
  const [removed] = await ctx.db
    .delete(schema.viewers)
    .where(and(eq(schema.viewers.hollerId, hollerId), eq(schema.viewers.memberId, memberId)))
    .returning();
  if (!removed) return;
  await recordChange(
    ctx,
    activityOf(ctx, { action: "viewer.removed", subjectType: "holler", subjectId: hollerId }),
    ctx.db.update(schema.recipients).set({ addedVia: "viewer" }),
  );
}
